function renderCheckboxFeeGroups() {
  const container = document.getElementById("fee-checkbox-groups-container");
  if (!container) return;

  const groupsMap = {};
  FEE_CHECKBOX_ITEMS.forEach(item => {
    if (!groupsMap[item.group]) groupsMap[item.group] = [];
    groupsMap[item.group].push(item);
  });

  let html = "";
  Object.keys(groupsMap).forEach(groupName => {
    const items = groupsMap[groupName];
    const groupIcon = items[0]?.icon || "fa-list";

    html += `
      <div class="fee-group-block">
        <div class="fee-group-header">
          <i class="fa-solid ${groupIcon}"></i> ${groupName}
        </div>
        <div class="fee-checkbox-grid">
    `;

    items.forEach(item => {
      html += `
        <div class="fee-checkbox-card" id="card-${item.id}" onclick="toggleFeeCard('${item.id}', event)">
          <div class="fee-card-left">
            <input type="checkbox" id="chk-${item.id}" class="fee-card-checkbox" onchange="onFeeCheckChange('${item.id}', this.checked, event)">
            <span class="fee-card-label">${item.label}</span>
          </div>
          <div class="fee-card-price-group" onclick="event.stopPropagation()">
            <span class="fee-card-price-prefix">RM</span>
            <input type="number" id="price-${item.id}" class="fee-card-price-input" min="0" value="${item.stdPrice}" oninput="onFeePriceInput('${item.id}')" onclick="event.stopPropagation()">
          </div>
        </div>
      `;
    });

    html += `
        </div>
      </div>
    `;
  });

  container.innerHTML = html;
}

function toggleFeeCard(itemId, event) {
  const chk = document.getElementById(`chk-${itemId}`);
  if (!chk) return;
  chk.checked = !chk.checked;
  onFeeCheckChange(itemId, chk.checked, event);
}

function onFeeCheckChange(itemId, isChecked, event) {
  if (event) event.stopPropagation();
  const card = document.getElementById(`card-${itemId}`);
  if (card) {
    if (isChecked) card.classList.add("checked");
    else card.classList.remove("checked");
  }
  updateTotalAmount();
}

function onFeePriceInput(itemId) {
  const chk = document.getElementById(`chk-${itemId}`);
  const card = document.getElementById(`card-${itemId}`);
  if (chk && !chk.checked) {
    chk.checked = true;
    if (card) card.classList.add("checked");
  }
  updateTotalAmount();
}

// Fee Input & Automatic Calculations
function initFeeCalculations() {
  renderCheckboxFeeGroups();

  document.getElementById("pay-date")?.addEventListener("change", renderReceiptPreview);
  document.getElementById("pay-month")?.addEventListener("change", renderReceiptPreview);

  document.querySelectorAll('input[name="kaedahBayaran"]').forEach(radio => {
    radio.addEventListener("change", renderReceiptPreview);
  });
}

let isTotalCustomEdited = false;

function calculateTotal() {
  const customTotalEl = document.getElementById("fee-total-custom");
  if (isTotalCustomEdited && customTotalEl && customTotalEl.value !== "") {
    return parseFloat(customTotalEl.value) || 0;
  }

  let totalSum = 0;
  FEE_CHECKBOX_ITEMS.forEach(item => {
    const chk = document.getElementById(`chk-${item.id}`);
    const priceEl = document.getElementById(`price-${item.id}`);
    if (chk && chk.checked && priceEl) {
      totalSum += (parseFloat(priceEl.value) || 0);
    }
  });

  return totalSum;
}

function updateTotalAmount() {
  const customTotalEl = document.getElementById("fee-total-custom");
  const calculatedSum = calculateTotal();

  if (!isTotalCustomEdited && customTotalEl) {
    customTotalEl.value = calculatedSum > 0 ? calculatedSum : "";
  }

  renderReceiptPreview();
}

function onCustomTotalInput() {
  const customTotalEl = document.getElementById("fee-total-custom");
  if (customTotalEl && customTotalEl.value.trim() !== "") {
    isTotalCustomEdited = true;
  } else {
    isTotalCustomEdited = false;
  }
  renderReceiptPreview();
}

// Calculate Next Receipt Number
function calculateNextReceiptNo() {
  if (appState.payments.length === 0) {
    appState.currentReceiptNo = "FQC-1100";
    return;
  }

  let maxNo = 1099;
  appState.payments.forEach(p => {
    if (p.noResit) {
      const numOnly = parseInt(p.noResit.replace(/[^0-9]/g, ""), 10);
      if (!isNaN(numOnly) && numOnly > maxNo) {
        maxNo = numOnly;
      }
    }
  });

  const nextNum = maxNo + 1;
  appState.currentReceiptNo = `FQC-${nextNum}`;
  const el = document.getElementById("receipt-no-display");
  if (el) el.innerText = appState.currentReceiptNo;
}

// Format Malaysian Phone Number for WhatsApp
function formatWhatsAppPhone(phoneStr) {
  if (!phoneStr) return "";
  let clean = phoneStr.replace(/[^0-9]/g, "");
  if (clean.startsWith("0")) {
    clean = "6" + clean;
  }
  return clean;
}

// Format Date string DD/MM/YYYY
function formatDateDisplay(dateStr) {
  if (!dateStr) return "";
  if (dateStr.includes("/")) return dateStr;
  const parts = dateStr.split("-");
  if (parts.length === 3) {
    return `${parts[2]}/${parts[1]}/${parts[0]}`;
  }
  return dateStr;
}

// ==============================================================================
// RENDER OFFICIAL FQC DIGITAL RECEIPT PREVIEW
// ==============================================================================
function renderReceiptPreview() {
  const studentName = appState.selectedStudent ? appState.selectedStudent.nama : (document.getElementById("student-search-input")?.value || "NAMA MURID");
  const rawDate = document.getElementById("pay-date")?.value || new Date().toISOString().split("T")[0];
  const dateFormatted = formatDateDisplay(rawDate);
  const bulan = document.getElementById("pay-month")?.value || "OGOS";
  const noResit = appState.currentReceiptNo || "FQC-1100";
  const kaedah = document.querySelector('input[name="kaedahBayaran"]:checked')?.value || "TUNAI";

  // Elements
  const elDate = document.getElementById("rc-date");
  const elMonth = document.getElementById("rc-month");
  const elNo = document.getElementById("rc-no");
  const elName = document.getElementById("rc-student-name");
  const elMethod = document.getElementById("rc-payment-method");
  const elTotal = document.getElementById("rc-total-amount");

  if (elDate) elDate.innerText = dateFormatted;
  if (elMonth) elMonth.innerText = bulan;
  if (elNo) elNo.innerText = noResit;
  if (elName) elName.innerText = studentName;
  if (elMethod) elMethod.innerText = kaedah;

  // Category Items Table
  const tableBody = document.getElementById("rc-table-body");
  if (!tableBody) return;

  let html = "";
  let totalAmount = 0;
  let hasItems = false;

  // Render ONLY items that are checked (TICKED) by Admin
  FEE_CHECKBOX_ITEMS.forEach(item => {
    const chk = document.getElementById(`chk-${item.id}`);
    const priceEl = document.getElementById(`price-${item.id}`);
    if (chk && chk.checked && priceEl) {
      const priceVal = parseFloat(priceEl.value) || 0;
      hasItems = true;
      totalAmount += priceVal;

      html += `
        <tr class="active-item">
          <td>${item.label}</td>
          <td style="text-align:center;">-</td>
          <td style="text-align:center;">${bulan}</td>
          <td class="amount-cell">${priceVal.toFixed(0)}</td>
        </tr>
      `;
    }
  });

  if (!hasItems) {
    html = `
      <tr>
        <td colspan="4" style="text-align:center; color:var(--text-muted); font-style:italic; padding:12px;">
          Sila tick kotak bayaran yuran di sebelah kiri
        </td>
      </tr>
    `;
  }

  // If custom total is edited, override totalAmount display
  const customTotalVal = document.getElementById("fee-total-custom")?.value;
  if (isTotalCustomEdited && customTotalVal !== "") {
    totalAmount = parseFloat(customTotalVal) || 0;
  }

  tableBody.innerHTML = html;
  if (elTotal) elTotal.innerText = `RM${totalAmount.toFixed(0)}`;
}

// ==============================================================================
// FORM VALIDATION & ACTIONS
// ==============================================================================
function validateForm() {
  const studentName = appState.selectedStudent ? appState.selectedStudent.nama : (document.getElementById("student-search-input")?.value || "").trim();
  const dateVal = document.getElementById("pay-date")?.value;
  const monthVal = document.getElementById("pay-month")?.value;
  const methodVal = document.querySelector('input[name="kaedahBayaran"]:checked')?.value;
  const total = calculateTotal();

  if (!studentName) {
    showToast("Sila pilih atau masukkan nama murid.", "warning");
    document.getElementById("student-search-input")?.focus();
    return false;
  }

  if (!dateVal) {
    showToast("Sila pilih tarikh pembayaran.", "warning");
    return false;
  }

  if (!monthVal) {
    showToast("Sila pilih bulan bayaran.", "warning");
    return false;
  }

  if (total <= 0) {
    showToast("Sila masukkan sekurang-kurangnya satu bayaran yuran > RM0.", "warning");
    return false;
  }

  if (!methodVal) {
    showToast("Sila pilih kaedah bayaran (TUNAI / TRANSFER).", "warning");
    return false;
  }

  return true;
}

// Action: JANA RESIT
function actionJanaResit() {
  if (!validateForm()) return;
  renderReceiptPreview();
  showToast("Resit rasmi FQC berjaya dijana!", "success");

  // Scroll to receipt preview on mobile
  const receiptCard = document.getElementById("receipt-card-printable");
  if (receiptCard && window.innerWidth <= 1100) {
    receiptCard.scrollIntoView({ behavior: "smooth" });
  }
}

// Action: SIMPAN PEMBAYARAN
async function actionSimpanPembayaran() {
  if (!validateForm()) return false;

  const btnSimpan = document.getElementById("btn-simpan");
  const btnWhatsapp = document.getElementById("btn-whatsapp");

  try {
    // Prevent Double Submit
    if (btnSimpan) btnSimpan.disabled = true;
    if (btnWhatsapp) btnWhatsapp.disabled = true;

    showLoading(true, "Menyimpan pembayaran ke Google Sheets...");

    const phone = appState.selectedStudent ? appState.selectedStudent.phone : (document.getElementById("parent-phone-display")?.value || "");
    const studentName = appState.selectedStudent ? appState.selectedStudent.nama : document.getElementById("student-search-input")?.value;
    const rawDate = document.getElementById("pay-date")?.value;
    const dateFormatted = formatDateDisplay(rawDate);
    const monthVal = document.getElementById("pay-month")?.value;
    const methodVal = document.querySelector('input[name="kaedahBayaran"]:checked')?.value;
    const catatanVal = document.getElementById("pay-catatan")?.value || "";

    let hargaStandardTotal = 0;
    let jumlahDiskaunTotal = 0;
    const checkedItems = [];
    const categoryTotals = {
      pendaftaran: 0,
      pengajianAlquran: 0,
      kelasUpkk: 0,
      kelasPsra: 0,
      kelasKhasJawi: 0,
      bukuRekodModul: 0,
      sumbangan: 0,
      kelasKafa: 0,
      kelasAkademik: 0,
      transit: 0
    };

    FEE_CHECKBOX_ITEMS.forEach(item => {
      const chk = document.getElementById(`chk-${item.id}`);
      const priceEl = document.getElementById(`price-${item.id}`);
      if (chk && chk.checked && priceEl) {
        const paidPrice = parseFloat(priceEl.value) || 0;
        hargaStandardTotal += item.stdPrice;
        if (item.stdPrice > paidPrice) {
          jumlahDiskaunTotal += (item.stdPrice - paidPrice);
        }
        if (categoryTotals[item.field] !== undefined) {
          categoryTotals[item.field] += paidPrice;
        }
        checkedItems.push({
          id: item.id,
          label: item.label,
          stdPrice: item.stdPrice,
          paidPrice: paidPrice
        });
      }
    });

    const paymentObj = {
      noResit: appState.currentReceiptNo,
      tarikh: dateFormatted,
      bulan: monthVal,
      namaMurid: studentName,
      noWhatsapp: phone,
      pendaftaran: categoryTotals.pendaftaran,
      pengajianAlquran: categoryTotals.pengajianAlquran,
      kelasUpkk: categoryTotals.kelasUpkk,
      kelasPsra: categoryTotals.kelasPsra,
      kelasKhasJawi: categoryTotals.kelasKhasJawi,
      bukuRekodModul: categoryTotals.bukuRekodModul,
      sumbangan: categoryTotals.sumbangan,
      kelasKafa: categoryTotals.kelasKafa,
      kelasAkademik: categoryTotals.kelasAkademik,
      transit: categoryTotals.transit,
      hargaStandard: hargaStandardTotal,
      jumlahDiskaun: jumlahDiskaunTotal,
      sebabDiskaun: jumlahDiskaunTotal > 0 ? "Harga Khas Murid" : "-",
      butiranItem: JSON.stringify(checkedItems),
      jumlah: calculateTotal(),
      kaedahBayaran: methodVal,
      catatan: catatanVal,
      timestamp: new Date().toISOString()
    };

    // Attempt save to Apps Script backend if configured
    if (appState.appsScriptUrl) {
      try {
        const response = await fetch(appState.appsScriptUrl, {
          method: "POST",
          headers: { "Content-Type": "text/plain;charset=utf-8" },
          body: JSON.stringify({ action: "savePayment", payload: paymentObj })
        });
        const resJson = await response.json();
        if (resJson.success && resJson.noResit) {
          paymentObj.noResit = resJson.noResit;
        }
      } catch (err) {
        console.warn("Backend save notice:", err);
      }
    }

    // Save locally
    appState.payments.unshift(paymentObj);
    appState.lastSavedPayment = paymentObj;
    saveLocalStoragePayments();

    showLoading(false);
    showToast(`Pembayaran berjaya disimpan. No. Resit: ${paymentObj.noResit}`, "success");

    // Recalculate next receipt no & refresh UI
    calculateNextReceiptNo();
    renderDashboard();
    renderHistoryTable();

    return paymentObj;
  } catch (e) {
    showLoading(false);
    showToast("Gagal menyimpan pembayaran: " + e.message, "error");
    return false;
  } finally {
    if (btnSimpan) btnSimpan.disabled = false;
    if (btnWhatsapp) btnWhatsapp.disabled = false;
  }
}

// Action: HANTAR WHATSAPP (Direct Launch, No Popup Blocker Delay)
async function actionHantarWhatsapp() {
  if (!validateForm()) return;

  const studentSearchEl = document.getElementById("student-search-input");
  const phoneEl = document.getElementById("parent-phone-display");
  const dateEl = document.getElementById("pay-date");
  const monthEl = document.getElementById("pay-month");

  const studentName = appState.selectedStudent ? appState.selectedStudent.nama : (studentSearchEl ? studentSearchEl.value : "Murid");
  const rawPhone = phoneEl ? phoneEl.value : (appState.selectedStudent ? appState.selectedStudent.phone : "");
  const rawDate = dateEl ? dateEl.value : new Date().toISOString().split("T")[0];
  const kaedahRadio = document.querySelector("input[name='kaedahBayaran']:checked");

  let noResit = appState.currentReceiptNo || "FQC-1100";
  let tarikh = typeof formatDateDisplay === "function" ? formatDateDisplay(rawDate) : rawDate;
  let bulan = monthEl ? monthEl.value : "";
  let jumlah = typeof calculateTotalAmount === "function" ? calculateTotalAmount() : 0;
  let kaedah = kaedahRadio ? kaedahRadio.value : "TUNAI";

  // Sekiranya rekod pembayaran murid ini baru disimpan, guna data tepat dari rekod simpanan!
  if (appState.lastSavedPayment && appState.lastSavedPayment.namaMurid === studentName) {
    noResit = appState.lastSavedPayment.noResit;
    if (appState.lastSavedPayment.tarikh) tarikh = appState.lastSavedPayment.tarikh;
    if (appState.lastSavedPayment.bulan) bulan = appState.lastSavedPayment.bulan;
    if (appState.lastSavedPayment.jumlah) jumlah = appState.lastSavedPayment.jumlah;
    if (appState.lastSavedPayment.kaedahBayaran) kaedah = appState.lastSavedPayment.kaedahBayaran;
  }

  const formattedPhone = typeof formatWhatsAppPhone === "function" ? formatWhatsAppPhone(rawPhone) : rawPhone.replace(/[^0-9]/g, '');
  const msg = `Assalamualaikum / Salam sejahtera.

Resit Pembayaran Yuran Fathul Quranic Centre (FQC)

Nama Murid: ${studentName}
No. Resit: ${noResit}
Tarikh: ${tarikh}
Bulan: ${bulan}
Jumlah Bayaran: RM${jumlah.toFixed(2)}
Kaedah Bayaran: ${kaedah}

Resit rasmi dilampirkan untuk rujukan.

Terima kasih.
Fathul Quranic Centre (FQC)`;

  const encodedMsg = encodeURIComponent(msg);
  const waUrl = formattedPhone ? `https://wa.me/${formattedPhone}?text=${encodedMsg}` : `https://wa.me/?text=${encodedMsg}`;

  // Buka WhatsApp serta-merta tanpa disekat oleh browser Pop-up Blocker
  window.open(waUrl, "_blank");

  // Jana gambar PNG resit secara latar belakang
  try {
    showLoading(true, "Menjana resit PNG...");
    const canvas = await generateReceiptCanvas();
    const studentNameClean = studentName.replace(/[^a-zA-Z0-9]/g, "_");
    const fileName = `FQC_Resit_${noResit}_${studentNameClean}.png`;

    const blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/png'));
    triggerDownloadBlob(blob, fileName);
    showLoading(false);
    showToast("WhatsApp dibuka & resit PNG dimuat turun!", "success");
  } catch (err) {
    showLoading(false);
    showToast("WhatsApp dibuka! (Muat turun PNG: " + err.message + ")", "warning");
  }
}

// Action: SIMPAN & WHATSAPP (Legacy Combo)
async function actionSimpanDanWhatsapp() {
  const savedRecord = await actionSimpanPembayaran();
  if (!savedRecord) return;
  await actionHantarWhatsapp();
}

