// ==============================================================================
// DASHBOARD & HISTORY TABLE
// ==============================================================================
function renderDashboard() {
  const todayStr = formatDateDisplay(new Date().toISOString().split("T")[0]);
  const monthsMalay = ["JANUARI", "FEBRUARI", "MAC", "APRIL", "MEI", "JUN", "JULAI", "OGOS", "SEPTEMBER", "OKTOBER", "NOVEMBER", "DISEMBER"];
  const currentMonth = monthsMalay[new Date().getMonth()];

  let totalToday = 0;
  let totalMonth = 0;
  let discountMonth = 0;

  appState.payments.forEach(p => {
    if (p.tarikh === todayStr) {
      totalToday += p.jumlah || 0;
    }
    if (p.bulan && p.bulan.toUpperCase() === currentMonth) {
      totalMonth += p.jumlah || 0;
      discountMonth += (p.jumlahDiskaun || 0);
    }
  });

  const elToday = document.getElementById("dash-total-today");
  const elMonth = document.getElementById("dash-total-month");
  const elDiscount = document.getElementById("dash-total-discount-month");
  const elSpecialCount = document.getElementById("dash-special-rate-count");
  const elCount = document.getElementById("dash-total-transactions");
  const elStudents = document.getElementById("dash-total-students");

  if (elToday) elToday.innerText = `RM ${totalToday.toFixed(2)}`;
  if (elMonth) elMonth.innerText = `RM ${totalMonth.toFixed(2)}`;
  if (elDiscount) elDiscount.innerText = `RM ${discountMonth.toFixed(2)}`;
  if (elSpecialCount) elSpecialCount.innerText = Array.isArray(appState.specialRates) ? appState.specialRates.length : 0;
  if (elCount) elCount.innerText = appState.students.length;

  // Recent 5 Payments Table
  const tbody = document.getElementById("dash-recent-tbody");
  if (!tbody) return;

  const recent = appState.payments.slice(0, 5);
  if (recent.length === 0) {
    tbody.innerHTML = `<tr><td colspan="6" style="text-align:center; color:var(--text-muted);">Belum ada rekod pembayaran</td></tr>`;
    return;
  }

  tbody.innerHTML = recent.map(p => `
    <tr>
      <td><strong>${p.noResit}</strong></td>
      <td>${p.tarikh}</td>
      <td>${p.namaMurid}</td>
      <td>${p.bulan}</td>
      <td style="font-weight:700; color:var(--primary-dark);">RM ${p.jumlah.toFixed(2)}</td>
      <td><span class="badge badge-success">${p.kaedahBayaran}</span></td>
    </tr>
  `).join("");
}

function renderHistoryTable() {
  const tbody = document.getElementById("history-tbody");
  if (!tbody) return;

  const query = (document.getElementById("history-search-input")?.value || "").toLowerCase();
  const monthFilter = (document.getElementById("history-month-filter")?.value || "").toUpperCase();

  const filtered = appState.payments.filter(p => {
    const matchQuery = !query || 
      p.namaMurid.toLowerCase().includes(query) || 
      p.noResit.toLowerCase().includes(query) || 
      (p.noWhatsapp && p.noWhatsapp.includes(query));
    
    const matchMonth = !monthFilter || (p.bulan && p.bulan.toUpperCase() === monthFilter);

    return matchQuery && matchMonth;
  });

  if (filtered.length === 0) {
    tbody.innerHTML = `<tr><td colspan="8" style="text-align:center; color:var(--text-muted); padding:1.5rem;">Tiada rekod pembayaran dijumpai.</td></tr>`;
    return;
  }

  tbody.innerHTML = filtered.map(p => `
    <tr>
      <td><strong>${p.noResit}</strong></td>
      <td>${p.tarikh}</td>
      <td><strong>${p.namaMurid}</strong></td>
      <td>${p.bulan}</td>
      <td style="font-weight:800; color:var(--primary-dark);">RM ${p.jumlah.toFixed(2)}</td>
      <td><span class="badge badge-info">${p.kaedahBayaran}</span></td>
      <td>${p.noWhatsapp || '-'}</td>
      <td>
        <div style="display:flex; gap:0.4rem;">
          <button class="btn btn-outline" style="padding:0.35rem 0.6rem; font-size:0.75rem;" onclick="viewHistoryReceipt('${p.noResit}')" title="Lihat Resit">
            <i class="fa-solid fa-eye"></i> Resit
          </button>
          <button class="btn btn-whatsapp" style="padding:0.35rem 0.6rem; font-size:0.75rem;" onclick="reSendWhatsapp('${p.noResit}')" title="WhatsApp Parent">
            <i class="fa-brands fa-whatsapp"></i> WA
          </button>
        </div>
      </td>
    </tr>
  `).join("");
}

function viewHistoryReceipt(noResit) {
  const payment = appState.payments.find(p => p.noResit === noResit);
  if (!payment) return;

  // Load into preview
  appState.selectedStudent = { nama: payment.namaMurid, phone: payment.noWhatsapp };
  appState.currentReceiptNo = payment.noResit;

  document.getElementById("pay-date").value = payment.tarikh;
  document.getElementById("pay-month").value = payment.bulan;

  renderReceiptPreview();

  // Open Modal View
  const modal = document.getElementById("receipt-modal");
  const modalContent = document.getElementById("modal-receipt-container");
  if (modal && modalContent) {
    const printableClone = document.getElementById("receipt-card-printable").cloneNode(true);
    modalContent.innerHTML = "";
    modalContent.appendChild(printableClone);
    modal.classList.add("show");
  }
}

function closeModal() {
  document.getElementById("receipt-modal")?.classList.remove("show");
}

function reSendWhatsapp(noResit) {
  const payment = appState.payments.find(p => p.noResit === noResit);
  if (!payment) return;

  const formattedPhone = formatWhatsAppPhone(payment.noWhatsapp);
  const msg = `Assalamualaikum / Salam sejahtera.

Peringatan Resit Pembayaran Fathul Quranic Centre (FQC).

Nama Murid: ${payment.namaMurid}
No. Resit: ${payment.noResit}
Tarikh: ${payment.tarikh}
Bulan: ${payment.bulan}
Jumlah: RM${payment.jumlah.toFixed(2)}
Kaedah: ${payment.kaedahBayaran}

Terima kasih.
Fathul Quranic Centre (FQC)`;

  const url = formattedPhone ? `https://wa.me/${formattedPhone}?text=${encodeURIComponent(msg)}` : `https://wa.me/?text=${encodeURIComponent(msg)}`;
  window.open(url, "_blank");
}

// ==============================================================================
// LOCAL STORAGE & BACKEND SYNC
// ==============================================================================
function saveLocalStoragePayments() {
  localStorage.setItem("fqc_payments_db", JSON.stringify(appState.payments));
}

function loadLocalStoragePayments() {
  const saved = localStorage.getItem("fqc_payments_db");
  if (saved) {
    try {
      appState.payments = JSON.parse(saved);
    } catch (e) {
      appState.payments = [];
    }
  }
}

function normalizeStudents(list) {
  if (!Array.isArray(list) || list.length === 0) return MASTER_STUDENTS_DEFAULT;
  return list.map((s, idx) => {
    let nama = (s.nama || "").toString().trim();
    let phone = (s.phone || "").toString().trim();
    let id = s.id || (idx + 1);

    // Sekiranya backend memulangkan nombor telefon di ruangan 'nama' dan nama murid di ruangan 'id'
    const cleanNama = nama.replace(/[^0-9]/g, '');
    if (cleanNama.length >= 8 && (cleanNama.indexOf("01") === 0 || cleanNama.indexOf("601") === 0)) {
      if (typeof id === "string" && isNaN(id) && id.length > 2) {
        phone = nama;
        nama = id;
        id = idx + 1;
      }
    }

    return {
      id: id,
      nama: nama || "Murid " + (idx + 1),
      phone: phone
    };
  });
}

async function fetchStudentsFromBackend(showToastMsg = false) {
  if (!appState.appsScriptUrl) return;
  try {
    if (showToastMsg) showLoading(true, "Memuat turun data murid terkini dari Google Sheets...");
    const res = await fetch(`${appState.appsScriptUrl}?action=getStudents`);
    const data = await res.json();
    if (showToastMsg) showLoading(false);

    if (data.success && Array.isArray(data.data) && data.data.length > 0) {
      appState.students = normalizeStudents(data.data);
      initStudentSearch();
      if (showToastMsg) showToast(`Senarai ${appState.students.length} murid berjaya dikemaskini dari Google Sheets!`, "success");
    }
  } catch (err) {
    if (showToastMsg) {
      showLoading(false);
      showToast("Gagal memuat turun data murid: " + err.message, "error");
    }
    console.log("Using default master student database:", err);
  }
}

async function fetchPaymentHistoryFromBackend() {
  if (!appState.appsScriptUrl) return;
  try {
    const res = await fetch(`${appState.appsScriptUrl}?action=getPaymentHistory`);
    const data = await res.json();
    if (data.success && Array.isArray(data.data) && data.data.length > 0) {
      appState.payments = data.data;
      saveLocalStoragePayments();
      calculateNextReceiptNo();
      renderDashboard();
      renderHistoryTable();
    }
  } catch (err) {
    console.log("Using local payment history:", err);
  }
}

// Settings Manager & Image Asset Loader
function loadAssetUrls() {
  const logoEl = document.querySelectorAll(".img-target-logo");
  const sigEl = document.querySelectorAll(".img-target-signature");
  const bgEl = document.querySelectorAll(".img-target-bg");

  logoEl.forEach(img => img.src = appState.config.logoUrl || DEFAULT_PLACEHOLDERS.logo);
  sigEl.forEach(img => img.src = appState.config.signatureUrl || DEFAULT_PLACEHOLDERS.signature);
  bgEl.forEach(img => img.src = appState.config.backgroundUrl || DEFAULT_PLACEHOLDERS.background);

  // Set input values in Settings view
  const inputLogo = document.getElementById("setting-logo-url");
  const inputSig = document.getElementById("setting-sig-url");
  const inputBg = document.getElementById("setting-bg-url");
  const inputScript = document.getElementById("setting-script-url");

  if (inputLogo) inputLogo.value = appState.config.logoUrl;
  if (inputSig) inputSig.value = appState.config.signatureUrl;
  if (inputBg) inputBg.value = appState.config.backgroundUrl;
  if (inputScript) inputScript.value = appState.appsScriptUrl;
}

function saveSettings() {
  const inputLogo = document.getElementById("setting-logo-url")?.value.trim();
  const inputSig = document.getElementById("setting-sig-url")?.value.trim();
  const inputBg = document.getElementById("setting-bg-url")?.value.trim();
  const inputScript = document.getElementById("setting-script-url")?.value.trim();

  if (inputLogo) localStorage.setItem("fqc_logo_url", inputLogo);
  if (inputSig) localStorage.setItem("fqc_signature_url", inputSig);
  if (inputBg) localStorage.setItem("fqc_background_url", inputBg);
  if (inputScript) localStorage.setItem("fqc_apps_script_url", inputScript);

  appState.config.logoUrl = inputLogo || "assets/logo.png";
  appState.config.signatureUrl = inputSig || "assets/signature.png";
  appState.config.backgroundUrl = inputBg || "assets/pbaq-bg.png";
  appState.appsScriptUrl = inputScript || "";

  loadAssetUrls();
  renderReceiptPreview();
  showToast("Tetapan berjaya disimpan!", "success");
}

async function runDatabaseSetup() {
  if (!appState.appsScriptUrl) {
    showToast("Sila masukkan Web App URL Google Apps Script terlebih dahulu.", "warning");
    return;
  }

  showLoading(true, "Menjalankan setupDatabase() di Google Sheets...");
  try {
    const res = await fetch(appState.appsScriptUrl, {
      method: "POST",
      headers: { "Content-Type": "text/plain;charset=utf-8" },
      body: JSON.stringify({ action: "setupDatabase" })
    });
    const data = await res.json();
    showLoading(false);
    if (data.success) {
      showToast(data.message, "success");
      fetchStudentsFromBackend();
    } else {
      showToast("Gagal Setup: " + data.message, "error");
    }
  } catch (err) {
    showLoading(false);
    showToast("Ralat setupDatabase: " + err.message, "error");
  }
}

// Toast & Loading Helpers
function showToast(message, type = "info") {
  const toast = document.getElementById("toast");
  const toastMsg = document.getElementById("toast-msg");
  const toastIcon = document.getElementById("toast-icon");

  if (!toast || !toastMsg) return;

  toastMsg.innerText = message;
  toast.className = `toast ${type} show`;

  if (toastIcon) {
    if (type === "success") toastIcon.className = "fa-solid fa-circle-check";
    else if (type === "error") toastIcon.className = "fa-solid fa-circle-xmark";
    else if (type === "warning") toastIcon.className = "fa-solid fa-triangle-exclamation";
    else toastIcon.className = "fa-solid fa-circle-info";
  }

  setTimeout(() => {
    toast.classList.remove("show");
  }, 4000);
}

function showLoading(show, text = "Memproses...") {
  const loading = document.getElementById("loading");
  const loadingText = document.getElementById("loading-text");
  if (loadingText) loadingText.innerText = text;
  if (loading) {
    if (show) loading.classList.add("show");
    else loading.classList.remove("show");
  }
}
